steps.script:
$b='C:\TTiTTulares'
$o=@{checks=@{};processes=@();recoveryReceipts=@{}}
foreach($p in @('TTImageApprovalReceiver.cjs','TTImagesImmediateInbox.cjs','TTendenciasImageBridge.js','TTiTTularesImageBridge.js','TTendenciasWebImages.cjs','TTiTTularesWebImages.cjs')){$o.checks[$p]=Test-Path (Join-Path $b $p)}
$o.processes=@(Get-CimInstance Win32_Process -Filter "name='node.exe'" -ErrorAction SilentlyContinue|Where-Object { $_.CommandLine -match 'TTImageApprovalReceiver|TT(endencias|iTTulares)(ImageBridge|WebImages)' }|ForEach-Object { @{type=$(if($_.CommandLine -match 'TTImageApprovalReceiver'){'inbox'}elseif($_.CommandLine -match 'WebImages'){'publisher'}else{'generator'});pid=$_.ProcessId} })
foreach($n in @(9223,9234)){try{$r=Invoke-RestMethod "http://127.0.0.1:$n/json/version" -TimeoutSec 3;$o.recoveryReceipts[[string]$n]=!!$r.webSocketDebuggerUrl}catch{$o.recoveryReceipts[[string]$n]=$false}}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress -Depth 4))
